from pysat.solvers import Glucose3
from pysat.card import *
import itertools

# Social Golfers: 21 golfers, 7 groups of 3, 5 weeks
# Variables: x[w][p][g] = True if golfer p is in group g in week w
# w in 0..4, p in 0..20, g in 0..6

num_weeks = 5
num_golfers = 21
num_groups = 7
group_size = 3

# Create variable mapping: var(w, p, g) -> integer
def var(w, p, g):
    return w * num_golfers * num_groups + p * num_groups + g + 1

num_vars = num_weeks * num_golfers * num_groups

clauses = []

# Constraint 1: Each golfer is in exactly one group each week
for w in range(num_weeks):
    for p in range(num_golfers):
        # At least one group
        clauses.append([var(w, p, g) for g in range(num_groups)])
        # At most one group (pairwise negative)
        for g1 in range(num_groups):
            for g2 in range(g1+1, num_groups):
                clauses.append([-var(w, p, g1), -var(w, p, g2)])

# Constraint 2: Each group has exactly 3 golfers each week
for w in range(num_weeks):
    for g in range(num_groups):
        # At least 3 golfers - use cardinality constraint
        # For simplicity, let's use pairwise encoding for "at most 3"
        # and require at least 3
        golfers_in_group = [var(w, p, g) for p in range(num_golfers)]

        # At most 3: no 4 golfers can all be in the same group
        for combo in itertools.combinations(range(num_golfers), 4):
            clauses.append([-var(w, combo[0], g), -var(w, combo[1], g), 
                          -var(w, combo[2], g), -var(w, combo[3], g)])

        # At least 3: this is harder to encode directly
        # We'll use the fact that 21 golfers / 7 groups = 3 per group
        # If each golfer is in exactly one group and at most 3 per group,
        # then exactly 3 per group is automatic

# Constraint 3: No pair of golfers in same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        for w1 in range(num_weeks):
            for w2 in range(w1+1, num_weeks):
                for g in range(num_groups):
                    # If p1 and p2 are both in group g in week w1,
                    # they can't both be in group g in week w2
                    clauses.append([-var(w1, p1, g), -var(w1, p2, g), 
                                  -var(w2, p1, g), -var(w2, p2, g)])

print(f"Number of variables: {num_vars}")
print(f"Number of clauses: {len(clauses)}")

# Solve
solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    print("SAT!")

    # Extract solution
    # assignment[w][p] = group of golfer p in week w
    assignment = [[0]*num_golfers for _ in range(num_weeks)]

    for w in range(num_weeks):
        for p in range(num_golfers):
            for g in range(num_groups):
                v = var(w, p, g)
                if v in model:
                    assignment[w][p] = g

    # Verify solution
    print("\nVerifying solution...")

    # Check each week has valid partition
    for w in range(num_weeks):
        groups = {}
        for p in range(num_golfers):
            g = assignment[w][p]
            if g not in groups:
                groups[g] = []
            groups[g].append(p)

        for g in range(num_groups):
            if g not in groups or len(groups[g]) != 3:
                print(f"Week {w}, Group {g}: {groups.get(g, [])}")
                print("INVALID!")
                break
        else:
            continue
        break
    else:
        print("All weeks have valid partitions")

    # Check no pair appears together more than once
    pair_count = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            golfers_in_group = [p for p in range(num_golfers) if assignment[w][p] == g]
            for p1, p2 in itertools.combinations(golfers_in_group, 2):
                key = (min(p1, p2), max(p1, p2))
                pair_count[key] = pair_count.get(key, 0) + 1

    max_count = max(pair_count.values()) if pair_count else 0
    print(f"Max pair count: {max_count}")

    if max_count <= 1:
        print("VALID SOLUTION!")
        # Convert to flat list
        flat = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                flat.append(assignment[w][p])
        print(f"Solution length: {len(flat)}")
        print(f"Solution: {flat}")
    else:
        print("INVALID - some pairs appear together more than once")
else:
    print("UNSATISFIABLE")

solver.delete()

